// middleware.ts — shared-password "beta gate" that sits in front of the whole site.
//
// This is a separate layer from the app's Supabase auth. Supabase auth lives
// entirely in the browser (localStorage); this gate is a signed server-set
// cookie checked in middleware. They never touch each other: once a visitor is
// past this gate, the normal site — including Supabase login — works exactly as
// before.
//
// How it works:
//   - The shared password comes from SITE_PASSWORD (server-only env var).
//   - The gate cookie holds an HMAC-SHA256 of the password, keyed by
//     SITE_GATE_SECRET. On every request we recompute the expected token and
//     compare. This gives two independent revoke levers:
//       * Change SITE_PASSWORD  -> old password stops working (soft revoke).
//       * Change SITE_GATE_SECRET -> every existing cookie is invalidated and
//         everyone is re-prompted (hard revoke).
//   - Neither value is ever sent to the browser (no NEXT_PUBLIC_ prefix).
//
// Fail-open: if SITE_PASSWORD or SITE_GATE_SECRET is not set, the gate is
// disabled and requests pass through. This keeps local dev usable without the
// vars and avoids bricking the site on a config slip — so the gate is only
// active where BOTH vars are set (i.e. once configured in Vercel).

import { NextRequest, NextResponse } from 'next/server'

const COOKIE_NAME = 'cc_gate'
const UNLOCK_PATH = '/__gate'
const COOKIE_MAX_AGE = 60 * 60 * 24 * 30 // ~30 days, in seconds

// The Career Clear binoculars mark (public/logo-mark.png) embedded as a base64
// data URI. The gate is served from middleware BEFORE the app loads, so a normal
// <img src="/logo-mark.png"> can't be relied on — inlining the bytes guarantees
// the logo renders on the locked screen regardless of the matcher. This constant
// is generated from the PNG (see the placeholder injection in the build note);
// the value below is the real encoded image.
const LOGO_DATA_URI = 'data:image/png;base64,'

// --- crypto helpers (Edge runtime Web Crypto) ---------------------------------

function toHex(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer)
  let out = ''
  for (let i = 0; i < bytes.length; i++) {
    out += bytes[i].toString(16).padStart(2, '0')
  }
  return out
}

// Token bound to BOTH the password and the secret. Changing either changes the
// token, which is what powers the soft/hard revoke described above.
async function makeToken(password: string, secret: string): Promise<string> {
  const enc = new TextEncoder()
  const key = await crypto.subtle.importKey(
    'raw',
    enc.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  )
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(password))
  return toHex(sig)
}

// Length-safe, constant-time-ish comparison so a wrong cookie can't be probed
// byte by byte.
function safeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false
  let diff = 0
  for (let i = 0; i < a.length; i++) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i)
  }
  return diff === 0
}

// --- password form ------------------------------------------------------------

function formHtml(opts: { next: string; error?: boolean }): string {
  const error = opts.error
    ? '<p class="error">Incorrect password. Please try again.</p>'
    : ''
  // Dark navy→teal gradient screen mirroring the landing hero. The binoculars
  // mark is inlined (LOGO_DATA_URI) so it always renders on the locked screen,
  // and Playfair Display is loaded from Google Fonts for the wordmark, with a
  // graceful serif fallback if the font request is blocked.
  // The hidden "next" field round-trips the originally requested path so a
  // correct password lands the visitor where they were headed.
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <meta name="robots" content="noindex" />
  <title>Career Clear — Private Beta</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&family=Inter:wght@400;500;600&display=swap" rel="stylesheet" />
  <style>
    * { box-sizing: border-box; }
    :root {
      --navy: #1a2744;
      --teal: #2a9d8f;
      --teal-light: #3db89a;
    }
    body {
      margin: 0;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      background: linear-gradient(135deg, #1a2744 0%, #1f3e55 55%, #2a9d8f 140%);
      color: #ffffff;
      font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      padding: 24px;
    }
    .gate {
      width: 100%;
      max-width: 380px;
      text-align: center;
    }
    .logo {
      height: 120px;
      width: auto;
      display: block;
      margin: 0 auto 20px;
    }
    .brand {
      font-family: "Playfair Display", Georgia, "Times New Roman", serif;
      font-size: 34px;
      font-weight: 700;
      color: #ffffff;
      letter-spacing: -0.01em;
      margin: 0;
    }
    .sub {
      font-size: 15px;
      color: rgba(255,255,255,0.8);
      margin: 14px 0 28px;
      line-height: 1.55;
    }
    label {
      display: block;
      text-align: left;
      font-size: 13px;
      font-weight: 600;
      color: rgba(255,255,255,0.85);
      margin-bottom: 7px;
    }
    input[type="password"] {
      width: 100%;
      padding: 12px 13px;
      font-size: 15px;
      color: #ffffff;
      background: rgba(255,255,255,0.08);
      border: 1px solid rgba(255,255,255,0.25);
      border-radius: 8px;
      outline: none;
      transition: border-color 150ms ease, box-shadow 150ms ease;
    }
    input[type="password"]::placeholder { color: rgba(255,255,255,0.5); }
    input[type="password"]:focus {
      border-color: var(--teal);
      box-shadow: 0 0 0 3px rgba(42,157,143,0.35);
      background: rgba(255,255,255,0.12);
    }
    /* Keep autofilled text legible on the dark field */
    input:-webkit-autofill,
    input:-webkit-autofill:focus {
      -webkit-text-fill-color: #ffffff;
      -webkit-box-shadow: 0 0 0 1000px rgba(31,62,85,0.95) inset;
      caret-color: #ffffff;
    }
    button {
      width: 100%;
      margin-top: 18px;
      padding: 12px 13px;
      font-size: 15px;
      font-weight: 600;
      color: #ffffff;
      background: var(--teal);
      border: none;
      border-radius: 8px;
      cursor: pointer;
      transition: background-color 150ms ease;
    }
    button:hover { background: var(--teal-light); }
    .error { color: #fca5a5; font-size: 13px; margin: 16px 0 0; font-weight: 500; }
  </style>
</head>
<body>
  <main class="gate">
    <img class="logo" src="${LOGO_DATA_URI}" alt="Career Clear binoculars mark" />
    <h1 class="brand">Career Clear</h1>
    <p class="sub">This is a private beta. Please enter the access password.</p>
    <form method="POST" action="${UNLOCK_PATH}">
      <label for="password">Access password</label>
      <input id="password" name="password" type="password" autocomplete="current-password" autofocus required />
      <input type="hidden" name="next" value="${opts.next}" />
      <button type="submit">Enter</button>
      ${error}
    </form>
  </main>
</body>
</html>`
}

function htmlResponse(body: string, status: number): NextResponse {
  return new NextResponse(body, {
    status,
    headers: { 'content-type': 'text/html; charset=utf-8' },
  })
}

// Only allow same-origin relative paths through the "next" round-trip, so the
// gate can't be turned into an open redirect.
function safeNext(value: string | null | undefined): string {
  if (value && value.startsWith('/') && !value.startsWith('//')) return value
  return '/'
}

// --- middleware ---------------------------------------------------------------

export async function middleware(req: NextRequest) {
  const password = process.env.SITE_PASSWORD
  const secret = process.env.SITE_GATE_SECRET

  // Gate disabled unless both are configured (see fail-open note up top).
  if (!password || !secret) return NextResponse.next()

  const expected = await makeToken(password, secret)
  const { pathname } = req.nextUrl

  // Handle the unlock form submission.
  if (pathname === UNLOCK_PATH && req.method === 'POST') {
    const form = await req.formData()
    const submitted = String(form.get('password') ?? '')
    const next = safeNext(String(form.get('next') ?? '/'))

    if (safeEqual(submitted, password)) {
      const res = NextResponse.redirect(new URL(next, req.url))
      res.cookies.set(COOKIE_NAME, expected, {
        httpOnly: true,
        secure: true,
        sameSite: 'lax',
        path: '/',
        maxAge: COOKIE_MAX_AGE,
      })
      return res
    }
    // Wrong password: re-show the form with an error, preserving destination.
    return htmlResponse(formHtml({ next, error: true }), 401)
  }

  // Already unlocked? Let the request through to the normal site.
  const cookie = req.cookies.get(COOKIE_NAME)?.value
  if (cookie && safeEqual(cookie, expected)) {
    return NextResponse.next()
  }

  // Locked: show the password form. Round-trip the requested path so the user
  // lands where they intended after entering the password.
  return htmlResponse(formHtml({ next: safeNext(pathname) }), 401)
}

// Run on everything EXCEPT Next.js internals and static asset files, so CSS,
// images, fonts and JS load normally and the form/submit work. The /__gate
// path is intentionally NOT excluded — middleware needs to process its POST.
export const config = {
  matcher: [
    '/((?!_next/static|_next/image|favicon.ico|robots.txt|sitemap.xml|.*\\.(?:svg|png|jpg|jpeg|gif|webp|avif|ico|css|js|woff|woff2|ttf|otf|map)$).*)',
  ],
}
